      {term:'التوصيل على التوالي',definition:'توصيل بعقدة مسار رئيس واحد يمر فيه التيار عبر العناصر تباعاً.'},
      {term:'التوصيل على التوازي',definition:'توصيل يوفر أكثر من فرع للتيار بين نقاط مشتركة.'},
      {term:'الموصل والعازل',definition:'الموصل يسمح بحركة الشحنات بسهولة نسبية، والعازل يعيقها.'}
