    content:'في دائرة التوالي يؤدي فتح المسار الرئيس إلى توقف جميع العناصر فيه، أما دوائر التوازي فتسمح بفروع مستقلة نسبياً. تستخدم المنازل توصيلات مصممة للحماية والعمل المتوازي. تجارب الصف تستخدم بطاريات منخفضة الجهد فقط ولا تستخدم كهرباء المنزل.',
